  <div className="flex items-center justify-between">
    <span className="text-sm font-medium text-gray-400">{label}</span>
    <button
      onClick={() => onChange(!value)}
      className={`w-10 h-5 rounded-full relative transition-colors ${value ? 'bg-cyan-600' : 'bg-neutral-700'}`}
    >
      <div className={`absolute top-1 left-1 w-3 h-3 bg-white rounded-full transition-transform ${value ? 'translate-x-5' : 'translate-x-0'}`} />
    </button>
  </div>
);

const ColorInput: React.FC<{ label: string, value: string, onChange: (v: string) => void }> = ({ label, value, onChange }) => (
  <div className="flex items-center justify-between bg-neutral-900 p-2 rounded-md border border-white/5">
    <span className="text-xs font-bold text-gray-400">{label}</span>
    <div className="flex items-center gap-2">
      <div className="w-4 h-4 rounded-full border border-white/20" style={{ background: value }}></div>
      <input
        type="color"
        value={value}
        onChange={(e) => onChange(e.target.value)}
        className="opacity-0 absolute w-8 h-8 cursor-pointer"
      />
      <span className="text-xs font-mono text-gray-500">{value}</span>
    </div>
  </div>
);

export const SettingsPanel: React.FC<SettingsPanelProps> = ({ 
    config, 
    onUpdate, 
    data,
    onUpdateData,
    currentTime,
    onSeek,
    onAudioLayerAdd,
    audioLayers,
    onUpdateLayer,
    onRemoveLayer,
    onJsonUpload,
    onSrtUpload,
    onResetProject,
    eventBlocks,
    onUpdateEventBlocks,
    onAssetLoaded,
    customEffects = [],
    onUpdateCustomEffects
}) => {
  const [activeTab, setActiveTab] = useState<'project' | 'lyrics' | 'sections' | 'templates' | 'customize' | 'library' | 'guide'>('project');
  const [editingEffect, setEditingEffect] = useState<CustomEffect | null>(null);

  const bgInputRef = useRef<HTMLInputElement>(null);
  const fontInputRef = useRef<HTMLInputElement>(null);
  const jsonInputRef = useRef<HTMLInputElement>(null);
  const srtInputRef = useRef<HTMLInputElement>(null);
  const audioInputRef = useRef<HTMLInputElement>(null);

  const handleTemplateSelect = (template: RendererConfig) => {
    onUpdate(JSON.parse(JSON.stringify(template)));
  };

  const updateNested = (section: keyof RendererConfig, key: string, value: any) => {
    const newConfig = JSON.parse(JSON.stringify(config));
    // @ts-ignore
    newConfig[section][key] = value;
    onUpdate(newConfig);
  };

  const updateSectionStyle = (section: SectionType, key: keyof SectionStyle, value: any) => {
      const newConfig = JSON.parse(JSON.stringify(config));
      if (!newConfig.sectionStyles) newConfig.sectionStyles = {};
      if (!newConfig.sectionStyles[section]) newConfig.sectionStyles[section] = { enabled: false };

      // @ts-ignore
      newConfig.sectionStyles[section][key] = value;
      onUpdate(newConfig);
  };

  const handleBgUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          const url = URL.createObjectURL(file);
          const type = file.type.startsWith('video') ? 'video' : 'image';

          const newConfig = JSON.parse(JSON.stringify(config));
          newConfig.background.type = type;
          newConfig.background.url = url;
          onUpdate(newConfig);
          if(onAssetLoaded) onAssetLoaded('background', file);
      }
  };

  const handleFontUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
       const reader = new FileReader();
       reader.onload = (ev) => {
           if(ev.target?.result) {
               const fontName = 'CustomFont-' + Date.now();
               const fontFace = new FontFace(fontName, `url(${ev.target.result})`);
               fontFace.load().then((loadedFace) => {
                   document.fonts.add(loadedFace);
                   updateNested('font', 'family', fontName);
                   if(onAssetLoaded) onAssetLoaded('font', file, fontName);
               }).catch(err => console.error("Font load failed", err));
           }
       };
       reader.readAsDataURL(file);
    }
  };

  const handleJsonChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      if (event.target?.result) onJsonUpload(event.target.result as string);
    };
    reader.readAsText(file);
  };

  const handleSrtChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      if (event.target?.result) onSrtUpload(event.target.result as string);
    };
    reader.readAsText(file);
  };

  const handleAudioChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
        onAudioLayerAdd(file);
        if (audioInputRef.current) audioInputRef.current.value = '';
    }
  };

  // --- CUSTOM EFFECT HANDLERS ---
  const addNewEffect = (type: CustomEffectType) => {
      const newFx: CustomEffect = {
          id: `fx-${Date.now()}`,
          name: `New ${type === 'shader' ? 'Shader' : 'Camera'}`,
          type,
          code: type === 'shader' ? TEMPLATE_SHADER_GLSL : TEMPLATE_CAMERA_JS,
          active: false,
          description: "My custom effect"
      };
      if (onUpdateCustomEffects) onUpdateCustomEffects([...customEffects, newFx]);
      setEditingEffect(newFx);
  };

  const saveEffect = (fx: CustomEffect) => {
      if (!onUpdateCustomEffects) return;
      const exists = customEffects.find(e => e.id === fx.id);
      if (exists) {
          onUpdateCustomEffects(customEffects.map(e => e.id === fx.id ? fx : e));
      } else {
          onUpdateCustomEffects([...customEffects, fx]);
      }
      setEditingEffect(null);
  };

  const deleteEffect = (id: string) => {
      if (!onUpdateCustomEffects || !confirm("Delete this effect permanently?")) return;
      onUpdateCustomEffects(customEffects.filter(e => e.id !== id));
      if (editingEffect?.id === id) setEditingEffect(null);
  };

  const toggleEffect = (id: string) => {
      if (!onUpdateCustomEffects) return;
      onUpdateCustomEffects(customEffects.map(e => e.id === id ? { ...e, active: !e.active } : e));
  };

  const downloadTemplate = (content: string, filename: string) => {
      const blob = new Blob([content], { type: 'text/plain' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = filename;
      a.click();
      URL.revokeObjectURL(url);
  };

  return (
    <div className="h-full flex flex-col bg-neutral-800 border-r border-white/5 text-gray-200">

      {/* Tab Navigation */}
      <div className="flex border-b border-white/5 bg-neutral-900 overflow-x-auto no-scrollbar">
        {[
            { id: 'project', icon: FolderOpen, label: 'Files' },
            { id: 'lyrics', icon: Clock, label: 'Timeline' },
            { id: 'sections', icon: Tags, label: 'Parts' },
            { id: 'templates', icon: LayoutTemplate, label: 'Presets' },
            { id: 'customize', icon: Sliders, label: 'Style' },
            { id: 'library', icon: Code, label: 'Library' },
            { id: 'guide', icon: BookOpen, label: 'Guide' },
        ].map(tab => (
            <button 
              key={tab.id}
              onClick={() => setActiveTab(tab.id as any)}
              title={tab.label}
              className={`flex-1 min-w-[50px] py-4 text-[10px] font-bold uppercase flex flex-col items-center justify-center gap-1 transition-colors border-b-2 ${activeTab === tab.id ? 'text-cyan-400 border-cyan-400 bg-white/5' : 'text-gray-500 hover:text-gray-300 border-transparent'}`}
            >
              <tab.icon size={16} />
              {tab.label}
            </button>
        ))}
      </div>

      {/* Content Area */}
      <div className="flex-1 overflow-y-auto custom-scrollbar bg-neutral-800">

        {/* PROJECT TAB */}
        {activeTab === 'project' && (
             <div className="p-4 space-y-6">

                {/* Audio Mixer */}
                <section>
                    <div className="flex items-center justify-between mb-3">
                         <h3 className="text-xs font-bold text-gray-500 uppercase tracking-widest flex items-center gap-2">
                            <Layers size={14}/> Audio Mixer
                        </h3>
                        <button
                             onClick={() => audioInputRef.current?.click()}
                             className="text-[10px] bg-neutral-700 hover:bg-neutral-600 px-2 py-1 rounded flex items-center gap-1 transition-colors"
                        >
                            <Plus size={10} /> Add Layer
                        </button>
                        <input
                            type="file"
                            ref={audioInputRef}
                            onChange={handleAudioChange}
                            accept="audio/*"
                            className="hidden"
                        />
                    </div>

                    <div className="space-y-2">
                        {audioLayers.length === 0 ? (
                            <div className="text-center p-4 border border-dashed border-white/10 rounded-lg text-xs text-gray-500">
                                No audio tracks loaded.
                            </div>
                        ) : (
                            audioLayers.map(layer => (
                                <div key={layer.id} className="bg-neutral-900 border border-white/5 rounded-lg p-2.5">
                                    <div className="flex items-center justify-between mb-2">
                                        <div className="flex items-center gap-2 overflow-hidden">
                                            <Music size={12} className="text-cyan-500 shrink-0"/>
                                            <span className="text-xs font-bold truncate text-gray-300" title={layer.name}>{layer.name}</span>
                                        </div>
                                        <button 
                                            onClick={() => onRemoveLayer(layer.id)}
                                            className="text-neutral-500 hover:text-red-400 transition-colors"
                                        >
                                            <Trash2 size={12}/>
                                        </button>
                                    </div>

                                    <div className="flex items-center gap-2">
                                        <input 
                                            type="range" min="0" max="1" step="0.01"
                                            value={layer.volume}
                                            onChange={(e) => onUpdateLayer(layer.id, { volume: parseFloat(e.target.value) })}
                                            className="flex-1 h-1 bg-neutral-700 rounded-lg appearance-none cursor-pointer accent-cyan-400"
                                            title={`Volume: ${Math.round(layer.volume * 100)}%`}
                                        />
                                        <div className="flex items-center gap-1 shrink-0">
                                            <button
                                                onClick={() => onUpdateLayer(layer.id, { muted: !layer.muted })}
                                                className={`w-6 h-6 rounded flex items-center justify-center text-[10px] font-bold border transition-colors ${layer.muted ? 'bg-red-900/50 border-red-500/50 text-red-400' : 'bg-neutral-800 border-white/5 text-gray-400 hover:text-white'}`}
                                                title="Mute"
                                            >
                                                M
                                            </button>
                                            <button
                                                onClick={() => onUpdateLayer(layer.id, { solo: !layer.solo })}
                                                className={`w-6 h-6 rounded flex items-center justify-center text-[10px] font-bold border transition-colors ${layer.solo ? 'bg-yellow-900/50 border-yellow-500/50 text-yellow-400' : 'bg-neutral-800 border-white/5 text-gray-400 hover:text-white'}`}
                                                title="Solo"
                                            >
                                                S
                                            </button>
                                        </div>
                                    </div>
                                </div>
                            ))
                        )}
                    </div>
                </section>

                <section>
                    <h3 className="text-xs font-bold text-gray-500 uppercase tracking-widest mb-3 flex items-center gap-2">
                        <Type size={14}/> Lyrics Source
                    </h3>
                    <div className="grid grid-cols-2 gap-3">
                         <button
                            onClick={() => jsonInputRef.current?.click()}
                            className="flex flex-col items-center justify-center gap-2 p-4 bg-neutral-900 hover:bg-neutral-700 rounded-lg border border-white/5 transition-colors group"
                        >
                            <FileJson size={24} className="text-gray-500 group-hover:text-purple-400" />
                            <span className="text-xs font-bold text-gray-400 group-hover:text-white">Import JSON</span>
                        </button>
                        <input
                            type="file"
                            ref={jsonInputRef}
                            onChange={handleJsonChange}
                            accept=".json,application/json"
                            className="hidden"
                        />

                         <button
                            onClick={() => srtInputRef.current?.click()}
                            className="flex flex-col items-center justify-center gap-2 p-4 bg-neutral-900 hover:bg-neutral-700 rounded-lg border border-white/5 transition-colors group"
                        >
                            <FileText size={24} className="text-gray-500 group-hover:text-orange-400" />
                            <span className="text-xs font-bold text-gray-400 group-hover:text-white">Import SRT</span>
                        </button>
                        <input
                            type="file"
                            ref={srtInputRef}
                            onChange={handleSrtChange}
                            accept=".srt"
                            className="hidden"
                        />
                    </div>
                </section>

                <section>
                    <h3 className="text-xs font-bold text-gray-500 uppercase tracking-widest mb-3 flex items-center gap-2">
                         <ImageIcon size={14}/> Assets
                    </h3>
                    <div className="space-y-2">
                         <button 
                            onClick={() => bgInputRef.current?.click()}
                            className="w-full flex items-center justify-start gap-3 px-3 py-2 bg-neutral-900 hover:bg-neutral-700 rounded-lg border border-white/5 transition-colors text-sm text-gray-300"
                        >
                            <Upload size={16} className="text-gray-500"/>
                            Upload Background Media
                        </button>
                        <input type="file" ref={bgInputRef} onChange={handleBgUpload} accept="image/*,video/*" className="hidden"/>

                        <button 
                            onClick={() => fontInputRef.current?.click()}
                            className="w-full flex items-center justify-start gap-3 px-3 py-2 bg-neutral-900 hover:bg-neutral-700 rounded-lg border border-white/5 transition-colors text-sm text-gray-300"
                        >
                             <Type size={16} className="text-gray-500"/>
                             Upload Custom Font
                        </button>
                        <input type="file" ref={fontInputRef} onChange={handleFontUpload} accept=".ttf,.woff,.woff2,.otf" className="hidden"/>
                    </div>
                </section>

                <section className="pt-4 border-t border-white/5">
                    <button
                        onClick={onResetProject}
                        className="w-full flex items-center justify-center gap-2 px-3 py-2 bg-red-950/30 hover:bg-red-900/50 text-red-400 rounded-lg border border-red-900/50 transition-colors text-sm font-bold"
                    >
                        <Trash2 size={16} />
                        Reset Project Defaults
                    </button>
                </section>
             </div>
        )}

        {/* TIMELINE TAB */}
        {activeTab === 'lyrics' && (
            <TimelineEditor 
                data={data} 
                onUpdate={onUpdateData} 
                currentTime={currentTime}
                onSeek={onSeek}
                eventBlocks={eventBlocks}
                onUpdateEventBlocks={onUpdateEventBlocks}
            />
        )}

        {/* CUSTOMIZE TAB */}
        {activeTab === 'customize' && (
          <div className="p-4 space-y-6">
              <section>
                  <h3 className="text-xs font-bold text-gray-500 uppercase tracking-widest mb-3 flex items-center gap-2"><Aperture size={14}/> Global Effects</h3>
                  <div className="bg-neutral-900 p-3 rounded-lg border border-white/5 space-y-2">
                        <ToggleInput label="Chromatic Ab." value={config.effects.chromaticAberration} onChange={(v) => updateNested('effects', 'chromaticAberration', v)} />
                        <ToggleInput label="Scanlines" value={config.effects.scanlines} onChange={(v) => updateNested('effects', 'scanlines', v)} />
                        <ToggleInput label="Vignette" value={config.effects.vignette} onChange={(v) => updateNested('effects', 'vignette', v)} />
                        <ToggleInput label="Film Grain" value={config.effects.filmGrain} onChange={(v) => updateNested('effects', 'filmGrain', v)} />
                        <ToggleInput label="Glow" value={config.effects.glow > 0} onChange={(v) => updateNested('effects', 'glow', v ? 0.8 : 0)} />
                  </div>
              </section>

              {/* ACTIVE CUSTOM EFFECTS LIST IN CUSTOMIZE TAB */}
              {customEffects && customEffects.length > 0 && (
                  <section>
                      <h3 className="text-xs font-bold text-purple-500 uppercase tracking-widest mb-3 flex items-center gap-2"><Code size={14}/> User Effects</h3>
                      <div className="bg-neutral-900 p-3 rounded-lg border border-white/5 space-y-2">
                          {customEffects.map(fx => (
                              <ToggleInput 
                                key={fx.id} 
                                label={fx.name} 
                                value={fx.active} 
                                onChange={() => toggleEffect(fx.id)} 
                              />
                          ))}
                      </div>
                  </section>
              )}
          </div>
        )}

        {/* LIBRARY TAB */}
        {activeTab === 'library' && (
            <div className="p-4 space-y-6">
                {!editingEffect ? (
                    <>
                        <div className="flex gap-2 mb-4">
                            <button onClick={() => addNewEffect('shader')} className="flex-1 bg-cyan-900/40 border border-cyan-500/30 hover:bg-cyan-800/50 text-cyan-200 py-2 rounded-lg text-xs font-bold flex items-center justify-center gap-2">
                                <Plus size={14}/> New Shader FX
                            </button>
                            <button onClick={() => addNewEffect('camera')} className="flex-1 bg-purple-900/40 border border-purple-500/30 hover:bg-purple-800/50 text-purple-200 py-2 rounded-lg text-xs font-bold flex items-center justify-center gap-2">
                                <Plus size={14}/> New Camera FX
                            </button>
                        </div>

                        <div className="space-y-3">
                            {customEffects.length === 0 ? (
                                <div className="text-center text-gray-500 py-8 text-xs italic">
                                    No custom effects created yet.<br/>Use the buttons above or download templates from the Guide.
                                </div>
                            ) : (
                                customEffects.map(fx => (
                                    <div key={fx.id} className="bg-neutral-900 border border-white/5 rounded-lg p-3 group">
                                        <div className="flex items-center justify-between mb-2">
                                            <div className="flex items-center gap-2">
                                                <div className={`w-2 h-2 rounded-full ${fx.type === 'shader' ? 'bg-cyan-500' : 'bg-purple-500'}`} />
                                                <span className="font-bold text-sm text-gray-200">{fx.name}</span>
                                                {fx.active && <span className="text-[9px] bg-green-900 text-green-300 px-1 rounded uppercase">Active</span>}
                                            </div>
                                            <div className="flex gap-1">
                                                <button onClick={() => setEditingEffect(fx)} className="p-1.5 hover:bg-white/10 rounded text-gray-400 hover:text-white" title="Edit Code">
                                                    <Edit2 size={14}/>
                                                </button>
                                                <button onClick={() => toggleEffect(fx.id)} className="p-1.5 hover:bg-white/10 rounded text-gray-400 hover:text-white" title={fx.active ? "Disable" : "Enable"}>
                                                    <Play size={14} fill={fx.active ? "currentColor" : "none"}/>
                                                </button>
                                                <button onClick={() => deleteEffect(fx.id)} className="p-1.5 hover:bg-red-900/50 rounded text-gray-400 hover:text-red-400" title="Delete">
                                                    <Trash2 size={14}/>
                                                </button>
                                            </div>
                                        </div>
                                        <p className="text-[10px] text-gray-500 line-clamp-2 font-mono bg-black/30 p-1.5 rounded">
                                            {fx.description || "// No description"}
                                        </p>
                                    </div>
                                ))
                            )}
                        </div>
                    </>
                ) : (
                    <div className="flex flex-col h-full">
                        <div className="flex items-center justify-between mb-2">
                            <input 
                                value={editingEffect.name}
                                onChange={(e) => setEditingEffect({...editingEffect, name: e.target.value})}
                                className="bg-transparent text-sm font-bold border-b border-transparent focus:border-cyan-500 outline-none w-1/2"
                                placeholder="Effect Name"
                            />
                            <div className="flex gap-2">
                                <button onClick={() => setEditingEffect(null)} className="text-xs text-gray-400 hover:text-white">Cancel</button>
                                <button onClick={() => saveEffect(editingEffect)} className="text-xs bg-cyan-600 px-3 py-1 rounded text-white font-bold">Save</button>
                            </div>
                        </div>
                        <input 
                            value={editingEffect.description || ''}
                            onChange={(e) => setEditingEffect({...editingEffect, description: e.target.value})}
                            className="bg-neutral-900 text-xs text-gray-400 p-2 rounded mb-2 w-full outline-none"
                            placeholder="Short description..."
                        />
                        <div className="flex-1 bg-neutral-950 rounded border border-white/10 p-2 overflow-hidden flex flex-col">
                            <div className="text-[10px] text-gray-500 mb-1 font-mono">{editingEffect.type === 'shader' ? '// GLSL Fragment Shader Body' : '// JavaScript Camera Logic'}</div>
                            <textarea 
                                value={editingEffect.code}
                                onChange={(e) => setEditingEffect({...editingEffect, code: e.target.value})}
                                className="flex-1 bg-transparent text-xs font-mono text-green-400 outline-none resize-none leading-relaxed"
                                spellCheck={false}
                            />
                        </div>
                        <p className="text-[10px] text-gray-500 mt-2">
                            {editingEffect.type === 'shader' 
                                ? "Writes to 'color'. Use 'effect_main(vec3 color, vec2 uv)'." 
                                : "Executes per frame. Access 'ctx', 'time', 'bass'."}
                        </p>
                    </div>
                )}
            </div>
        )}

        {/* GUIDE TAB */}
        {activeTab === 'guide' && (
            <div className="p-4 space-y-6">
                <div className="text-center mb-4">
                    <BookOpen className="mx-auto text-cyan-500 mb-2" size={24}/>
                    <h2 className="text-sm font-bold text-white">Developer Guide</h2>
                    <p className="text-[10px] text-gray-400">Templates & Documentation</p>
                </div>

                <div className="space-y-4">
                    <div className="bg-neutral-900 p-3 rounded-lg border border-white/5">
                        <div className="flex justify-between items-center mb-2">
                            <span className="text-xs font-bold text-cyan-400">GLSL Shader Template</span>
                            <button onClick={() => downloadTemplate(TEMPLATE_SHADER_GLSL, 'custom_shader.glsl')} className="text-gray-400 hover:text-white"><Download size={14}/></button>
                        </div>
                        <p className="text-[10px] text-gray-500 mb-2">
                            Create custom visual effects using GLSL fragment shader logic. The function <code>effect_main</code> receives color and UVs.
                        </p>
                    </div>

                    <div className="bg-neutral-900 p-3 rounded-lg border border-white/5">
                        <div className="flex justify-between items-center mb-2">
                            <span className="text-xs font-bold text-purple-400">JS Camera Template</span>
                            <button onClick={() => downloadTemplate(TEMPLATE_CAMERA_JS, 'custom_camera.js')} className="text-gray-400 hover:text-white"><Download size={14}/></button>
                        </div>
                        <p className="text-[10px] text-gray-500 mb-2">
                            Manipulate the Canvas context 2D directly using JavaScript. Useful for custom rotations, zooms, and reactive transformations.
                        </p>
                    </div>

                    <div className="bg-neutral-900 p-3 rounded-lg border border-white/5">
                        <div className="flex justify-between items-center mb-2">
                            <span className="text-xs font-bold text-yellow-400">Event Preset JSON</span>
                            <button onClick={() => downloadTemplate(TEMPLATE_EVENT_PRESET, 'event_preset.json')} className="text-gray-400 hover:text-white"><Download size={14}/></button>
                        </div>
                        <p className="text-[10px] text-gray-500 mb-2">
                            Define a reusable block of effect overrides (glitches, shakes, toggles) to drag into your timeline.
                        </p>
                    </div>
                </div>
            </div>
        )}

        {/* TEMPLATES & SECTIONS TABS (Standard Content) */}
        {activeTab === 'templates' && (
          <div className="p-4 grid grid-cols-2 gap-3">
             {TEMPLATES.map(t => (
               <button
                 key={t.id}
                 onClick={() => handleTemplateSelect(t)}
                 className="flex flex-col items-start gap-2 p-3 bg-neutral-900 border border-white/5 hover:border-cyan-500/50 rounded-xl transition-all hover:bg-neutral-800 group text-left"
               >
                 <div className="w-full aspect-video bg-black/40 rounded-lg mb-1 overflow-hidden relative">
                    <div className="absolute inset-0 flex items-center justify-center">
                        <Sparkles className="text-gray-700 group-hover:text-cyan-500 transition-colors" />
                    </div>
                 </div>
                 <div>
                    <span className="text-sm font-bold block text-gray-200 group-hover:text-cyan-400">{t.name}</span>
                 </div>
               </button>
             ))}
          </div>
        )}

        {activeTab === 'sections' && (
             <div className="p-4 space-y-6">
                 {['verse', 'chorus', 'bridge', 'intro', 'outro'].map((sectionKey) => {
                     const key = sectionKey as SectionType;
                     const style = config.sectionStyles?.[key] || { enabled: false };
                     return (
                         <div key={key} className="bg-neutral-900 border border-white/5 rounded-lg p-3">
                             <div className="flex items-center justify-between mb-3 border-b border-white/5 pb-2">
                                 <h3 className="text-xs font-bold text-gray-200 uppercase tracking-widest">{key}</h3>
                                 <ToggleInput 
                                    label=""
                                    value={style.enabled} 
                                    onChange={(v) => updateSectionStyle(key, 'enabled', v)}
                                 />
                             </div>
                             {style.enabled && (
                                <div className="space-y-3">
                                    <div className="flex justify-between text-xs text-gray-400 mb-1">
                                        <span>Font Scale</span>
                                        <span>{Math.round((style.fontScale || 1.0) * 100)}%</span>
                                    </div>
                                    <input 
                                        type="range" min="0.5" max="2.0" step="0.1" 
                                        value={style.fontScale || 1.0} 
                                        onChange={(e) => updateSectionStyle(key, 'fontScale', parseFloat(e.target.value))}
                                        className="w-full h-1 bg-neutral-700 rounded-lg appearance-none cursor-pointer accent-cyan-400"
                                    />
                                     <ColorInput label="Active Color" value={style.colors_active || config.colors.active} onChange={(v) => updateSectionStyle(key, 'colors_active', v)} />
                                </div>
                             )}
                         </div>
                     )
                 })}
             </div>
        )}
      </div>
    </div>
  );
};

import React, { useEffect, useRef, useState } from 'react';
import { LyricData, Segment, Word, EventBlock, EffectOverrides, CustomEffect } from '../types';
import { Clock, Trash2, Plus, PlayCircle, Download, AlertCircle, ChevronDown, ChevronUp, Tag, X, FolderInput, Check, Zap, Eye, EyeOff, TrendingUp, TrendingDown } from 'lucide-react';

interface TimelineEditorProps {
  data: LyricData;
  onUpdate: (data: LyricData) => void;
  currentTime: number;
  onSeek: (time: number) => void;
  eventBlocks: EventBlock[];
  onUpdateEventBlocks: (blocks: EventBlock[]) => void;
  customEffects?: CustomEffect[]; // Added customEffects prop
}

// --- HELPER FUNCTIONS ---

const secondsToMMSS = (seconds: number): string => {
  const m = Math.floor(seconds / 60);
  const s = (seconds % 60).toFixed(2);
  const sStr = s.includes('.') ? s : `${s}.00`;
  return `${m.toString().padStart(2, '0')}:${sStr.padStart(5, '0')}`;
};

const mmssToSeconds = (timeStr: string): number => {
  const parts = timeStr.split(':');
  if (parts.length === 2) {
    const minutes = parseInt(parts[0], 10);
    const seconds = parseFloat(parts[1]);
    return (minutes * 60) + seconds;
  }
  return parseFloat(timeStr) || 0;
};

// Recalculates word timings linearly across the segment duration
const recalculateWords = (text: string, start: number, end: number): Word[] => {
  const lines = text.split('\n');
  const words: Word[] = [];
  const duration = Math.max(0.1, end - start);

  let totalWordCount = 0;
  lines.forEach(line => {
    totalWordCount += line.trim().split(/\s+/).filter(w => w.length > 0).length;
  });

  if (totalWordCount === 0) return [];

  const timePerWord = duration / totalWordCount;
  let currentWordIndex = 0;

  lines.forEach((line, lineIdx) => {
    const lineWords = line.trim().split(/\s+/).filter(w => w.length > 0);
    lineWords.forEach((w) => {
      const wordStart = start + (currentWordIndex * timePerWord);
      const wordEnd = wordStart + timePerWord;
      words.push({
        word: w,
        start: wordStart,
        end: wordEnd,
        probability: 1,
        line_number: lineIdx
      });
      currentWordIndex++;
    });
  });

  return words;
};

// --- SUB-COMPONENTS ---

const TimeInput = ({ 
  value, 
  onChange,
  className 
}: { 
  value: number, 
  onChange: (val: number) => void,
  className?: string 
}) => {
  const [localValue, setLocalValue] = useState(secondsToMMSS(value));
  const [isEditing, setIsEditing] = useState(false);

  useEffect(() => {
    if (!isEditing) {
      setLocalValue(secondsToMMSS(value));
    }
  }, [value, isEditing]);

  const handleBlur = () => {
    setIsEditing(false);
    const seconds = mmssToSeconds(localValue);
    onChange(seconds);
    setLocalValue(secondsToMMSS(seconds));
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') (e.target as HTMLInputElement).blur();
  };

  return (
    <input
      type="text"
      className={className}
      value={localValue}
      onChange={(e) => setLocalValue(e.target.value)}
      onFocus={() => setIsEditing(true)}
      onBlur={handleBlur}
      onKeyDown={handleKeyDown}
      placeholder="00:00.00"
    />
  );
};

const DebouncedTextArea = ({ 
    value, 
    onChange, 
    onBlur, 
    className, 
    rows,
    placeholder
}: { 
    value: string, 
    onChange: (val: string) => void, 
    onBlur: () => void,
    className?: string,
    rows?: number,
    placeholder?: string
}) => {
    const [localValue, setLocalValue] = useState(value);
    const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

    useEffect(() => { setLocalValue(value); }, [value]);

    const handleChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
        const newValue = e.target.value;
        setLocalValue(newValue);
        if (timeoutRef.current) clearTimeout(timeoutRef.current);
        timeoutRef.current = setTimeout(() => onChange(newValue), 300);
    };

    return (
        <textarea
            className={className}
            rows={rows}
            value={localValue}
            onChange={handleChange}
            onBlur={onBlur}
            placeholder={placeholder}
        />
    );
};

const EffectToggle = ({ label, isActive, onToggle }: { label: string, isActive: boolean | undefined, onToggle: () => void }) => {
    return (
        <button
            onClick={onToggle}
            className={`text-[10px] px-2 py-1 rounded border transition-colors ${
                isActive === true 
                ? 'bg-purple-600 border-purple-400 text-white font-bold shadow-[0_0_10px_rgba(147,51,234,0.3)]' 
                : isActive === false 
                ? 'bg-red-900/50 border-red-500/30 text-red-300 line-through decoration-red-500' // Forced Off
                : 'bg-neutral-800 border-white/5 text-gray-500 hover:border-white/20' // Global
            }`}
        >
            {label}
        </button>
    );
};

// --- MAIN COMPONENT ---

export const TimelineEditor: React.FC<TimelineEditorProps> = ({ 
    data, 
    onUpdate, 
    currentTime, 
    onSeek,
    eventBlocks,
    onUpdateEventBlocks,
    customEffects = []
}) => {
  const scrollRef = useRef<HTMLDivElement>(null);
  const [expandedSegments, setExpandedSegments] = useState<Set<string>>(new Set());
  const [editingSectionId, setEditingSectionId] = useState<string | null>(null);

  const toggleExpand = (id: string) => {
    const newSet = new Set(expandedSegments);
    if (newSet.has(id)) newSet.delete(id);
    else newSet.add(id);
    setExpandedSegments(newSet);
  };

  // --- DATA UPDATERS ---

  const updateSegmentData = (index: number, updates: Partial<Segment>, shouldRecalculateWords = false) => {
    const newSegments = [...data.segments];
    const oldSegment = newSegments[index];
    let updatedSegment = { ...oldSegment, ...updates };

    if (shouldRecalculateWords) {
         updatedSegment.words = recalculateWords(updatedSegment.text, updatedSegment.start, updatedSegment.end);
    } else if (updates.start !== undefined || updates.end !== undefined) {
         const oldDuration = oldSegment.end - oldSegment.start;
         const newDuration = updatedSegment.end - updatedSegment.start;
         if (oldDuration > 0 && updatedSegment.words.length > 0) {
             const ratio = newDuration / oldDuration;
             updatedSegment.words = oldSegment.words.map(w => ({
                 ...w,
                 start: updatedSegment.start + (w.start - oldSegment.start) * ratio,
                 end: updatedSegment.start + (w.end - oldSegment.start) * ratio
             }));
         } else {
             updatedSegment.words = recalculateWords(updatedSegment.text, updatedSegment.start, updatedSegment.end);
         }
    }
    newSegments[index] = updatedSegment;
    if (updates.start !== undefined) newSegments.sort((a, b) => a.start - b.start);
    onUpdate({ ...data, segments: newSegments });
  };

  const updateWordData = (segIndex: number, wordIndex: number, updates: Partial<Word>) => {
    const newSegments = [...data.segments];
    const segment = { ...newSegments[segIndex] };
    const newWords = [...segment.words];
    newWords[wordIndex] = { ...newWords[wordIndex], ...updates };
    segment.words = newWords;
    newSegments[segIndex] = segment;
    onUpdate({ ...data, segments: newSegments });
  };

  const handleDeleteSegment = (index: number) => {
    if(!confirm("Delete this lyric segment?")) return;
    const newSegments = [...data.segments];
    newSegments.splice(index, 1);
    onUpdate({ ...data, segments: newSegments });
  };

  const handleAddSegment = () => {
    const newSegments = [...data.segments];
    const lastSeg = newSegments[newSegments.length - 1];
    const newStart = lastSeg ? lastSeg.end + 0.2 : 0;
    const newSegment: Segment = {
        id: Date.now().toString(),
        start: newStart,
        end: newStart + 2.0,
        text: "New Line",
        section: undefined, 
        words: []
    };
    newSegment.words = recalculateWords(newSegment.text, newSegment.start, newSegment.end);
    newSegments.push(newSegment);
    onUpdate({ ...data, segments: newSegments });
  };

  // --- EVENT BLOCK UPDATERS ---

  const handleAddEventBlock = () => {
      const newBlock: EventBlock = {
          id: `evt-${Date.now()}`,
          start: currentTime,
          end: currentTime + 5,
          label: "FX Block",
          overrides: {},
          collapsed: false,
          smoothIn: false,
          smoothOut: false
      };
      onUpdateEventBlocks([...eventBlocks, newBlock].sort((a, b) => a.start - b.start));
  };

  const updateEventBlock = (id: string, updates: Partial<EventBlock>) => {
      let newBlocks = eventBlocks.map(b => b.id === id ? { ...b, ...updates } : b);
      if (updates.start !== undefined) newBlocks.sort((a, b) => a.start - b.start);
      onUpdateEventBlocks(newBlocks);
  };

  const toggleOverride = (blockId: string, key: keyof EffectOverrides) => {
      const block = eventBlocks.find(b => b.id === blockId);
      if(!block) return;

      const current = block.overrides[key];
      // Cycle: undefined (Global) -> true (On) -> false (Off) -> undefined
      let next: boolean | undefined;
      if (current === undefined) next = true;
      else if (current === true) next = false;
      else next = undefined;

      const newOverrides = { ...block.overrides, [key]: next };
      // Remove key if undefined to clean up
      if (next === undefined) delete newOverrides[key];

      updateEventBlock(blockId, { overrides: newOverrides });
  };

  const toggleCustomOverride = (blockId: string, effectId: string) => {
      const block = eventBlocks.find(b => b.id === blockId);
      if(!block) return;

      const currentMap = block.overrides.custom_fx || {};
      const current = currentMap[effectId];

      // Cycle: undefined -> true -> false -> undefined
      let next: boolean | undefined;
      if (current === undefined) next = true;
      else if (current === true) next = false;
      else next = undefined;

      const newMap = { ...currentMap, [effectId]: next };
      if (next === undefined) delete newMap[effectId];

      const newOverrides = { ...block.overrides };
      if (Object.keys(newMap).length === 0) {
          delete newOverrides.custom_fx;
      } else {
          // @ts-ignore - TS sometimes struggles with dynamic Record types in strict mode
          newOverrides.custom_fx = newMap;
      }

      updateEventBlock(blockId, { overrides: newOverrides });
  };

  const deleteEventBlock = (id: string) => {
      if(!confirm("Delete this event block?")) return;
      onUpdateEventBlocks(eventBlocks.filter(b => b.id !== id));
  };

  // --- RENDER HELPERS ---

  // Combine and sort lyrics and events for display
  const combinedItems = [
      ...data.segments.map((s, i) => ({ type: 'segment' as const, data: s, index: i, start: s.start })),
      ...eventBlocks.map((b, i) => ({ type: 'block' as const, data: b, index: i, start: b.start }))
  ].sort((a, b) => a.start - b.start);

  const SECTION_COLORS: Record<string, string> = {
      verse: 'border-blue-500',
      chorus: 'border-pink-500',
      bridge: 'border-yellow-500',
      intro: 'border-gray-500',
      outro: 'border-red-500'
  };

  const SECTION_BG: Record<string, string> = {
      verse: 'bg-blue-950/40 text-blue-200',
      chorus: 'bg-pink-950/40 text-pink-200',
      bridge: 'bg-yellow-950/40 text-yellow-200',
      intro: 'bg-gray-800/60 text-gray-300',
      outro: 'bg-red-950/40 text-red-200'
  };

  const getSectionColor = (name: string) => SECTION_COLORS[name.toLowerCase().split(' ')[0]] || 'border-gray-600';
  const getSectionBg = (name: string) => SECTION_BG[name.toLowerCase().split(' ')[0]] || 'bg-neutral-800 text-gray-400';

  let currentSection = 'verse'; 

  // Auto-scroll
  useEffect(() => {
    // Find active element
    const activeItem = combinedItems.find(item => {
        if(item.type === 'segment') return currentTime >= item.data.start && currentTime <= item.data.end;
        if(item.type === 'block') return currentTime >= item.data.start && currentTime <= item.data.end;
        return false;
    });

    if (activeItem && scrollRef.current) {
        const id = activeItem.type === 'segment' ? activeItem.data.id : activeItem.data.id;
        const row = scrollRef.current.querySelector(`[data-id="${id}"]`) as HTMLElement;
        if (row) {
             // Basic check to see if visible, if not scroll
            const container = scrollRef.current;
            const rowTop = row.offsetTop;
            const rowBottom = rowTop + row.offsetHeight;
            const containerTop = container.scrollTop;
            const containerBottom = containerTop + container.offsetHeight;
            if (rowTop < containerTop || rowBottom > containerBottom) {
                 row.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }
        }
    }
  }, [currentTime, combinedItems]);

  return (
    <div className="flex flex-col h-full bg-neutral-900 border-l border-white/5">

        {/* HEADER TOOLBAR */}
        <div className="p-3 border-b border-white/5 flex justify-between items-center bg-neutral-800 shrink-0">
            <div className="flex items-center gap-2">
                <Clock size={16} className="text-cyan-400" /> 
                <span className="text-xs font-bold text-gray-200 uppercase tracking-widest">Timeline</span>
            </div>

            <div className="flex gap-2">
                <button 
                    onClick={handleAddEventBlock}
                    className="text-[10px] flex items-center gap-1 bg-purple-900/50 hover:bg-purple-800/80 border border-purple-500/50 px-3 py-1.5 rounded text-purple-200 transition-colors font-bold"
                >
                    <Zap size={12} /> Add Event
                </button>
                <button 
                    onClick={handleAddSegment}
                    className="text-[10px] flex items-center gap-1 bg-cyan-900/50 hover:bg-cyan-800/80 border border-cyan-500/50 px-3 py-1.5 rounded text-cyan-200 transition-colors font-bold"
                >
                    <Plus size={12} /> Add Line
                </button>
            </div>
        </div>

        {/* LIST AREA */}
        <div className="flex-1 overflow-y-auto custom-scrollbar p-3 space-y-2" ref={scrollRef}>
            {combinedItems.length === 0 ? (
                <div className="flex flex-col items-center justify-center h-40 text-gray-500 border-2 border-dashed border-white/5 rounded-xl">
                    <AlertCircle className="mb-2 opacity-50" />
                    <span className="text-xs">Timeline Empty</span>
                    <span className="text-[10px] mt-1">Add a Lyric Line or FX Event</span>
                </div>
            ) : (
                combinedItems.map((item) => {
                    // --- RENDER LYRIC SEGMENT ---
                    if (item.type === 'segment') {
                        const seg = item.data;
                        const idx = item.index;
                        const isActive = currentTime >= seg.start && currentTime <= seg.end;
                        const isExpanded = expandedSegments.has(seg.id);
                        const isEditingSection = editingSectionId === seg.id;

                        // Handle Section Headers
                        const isNewSection = !!seg.section;
                        if (isNewSection) currentSection = seg.section!;
                        else if (idx === 0 && !seg.section) currentSection = 'verse'; 

                        return (
                             <div key={seg.id} className="flex flex-col gap-1">
                                {isNewSection && (
                                    <div className={`flex items-center justify-between px-3 py-1.5 rounded-md mt-2 mb-1 ${getSectionBg(currentSection)} border border-white/5 shadow-sm`}>
                                        <div className="flex items-center gap-2">
                                            <Tag size={12} className="opacity-70" />
                                            <span className="text-[10px] font-bold uppercase tracking-widest">{currentSection}</span>
                                        </div>
                                    </div>
                                )}
                                <div 
                                    data-id={seg.id}
                                    className={`group relative flex flex-col gap-2 p-3 rounded-r-lg border-t border-b border-r border-white/5 transition-all duration-200 border-l-4 ${getSectionColor(currentSection)} ${
                                        isActive ? 'bg-cyan-950/30 border-t-cyan-500/30 border-b-cyan-500/30' : 'bg-neutral-800 hover:border-r-white/20'
                                    }`}
                                >
                                    {isActive && <div className="absolute inset-0 border-2 border-cyan-500/20 rounded-r-lg pointer-events-none" />}

                                    {/* CONTROLS */}
                                    <div className="flex items-center justify-between gap-3">
                                        <div className="flex items-center gap-2 bg-neutral-950/50 p-1 rounded-md border border-white/5">
                                             <div className="flex flex-col px-1">
                                                <label className="text-[8px] text-cyan-500 font-bold uppercase">Start</label>
                                                <TimeInput className="bg-transparent w-16 text-xs font-mono text-gray-200 outline-none focus:text-white" value={seg.start} onChange={(val) => updateSegmentData(idx, { start: val })} />
                                            </div>
                                            <div className="w-px h-6 bg-white/10"></div>
                                            <div className="flex flex-col px-1">
                                                <label className="text-[8px] text-purple-500 font-bold uppercase">End</label>
                                                <TimeInput className="bg-transparent w-16 text-xs font-mono text-gray-200 outline-none focus:text-white" value={seg.end} onChange={(val) => updateSegmentData(idx, { end: val })} />
                                            </div>
                                        </div>
                                        <div className="flex items-center gap-1 opacity-60 group-hover:opacity-100 transition-opacity">
                                             {!isNewSection && (
                                                <button onClick={() => updateSegmentData(idx, { section: 'new section' })} className="p-1.5 rounded-md hover:bg-white/10 text-gray-400 hover:text-white" title="New Section">
                                                    <FolderInput size={14} />
                                                </button>
                                             )}
                                             <button onClick={() => onSeek(seg.start)} className={`p-1.5 rounded-md transition-colors ${isActive ? 'bg-cyan-500 text-black' : 'hover:bg-white/10 text-gray-400'}`}>
                                                 <PlayCircle size={14} fill={isActive ? "currentColor" : "none"} />
                                             </button>
                                             <button onClick={() => handleDeleteSegment(idx)} className="p-1.5 rounded-md hover:bg-red-500/20 text-gray-500 hover:text-red-400">
                                                 <Trash2 size={14} />
                                             </button>
                                        </div>
                                    </div>

                                    {/* TEXT */}
                                    <DebouncedTextArea
                                        className={`w-full bg-neutral-900/50 rounded-md p-2 text-sm outline-none resize-none font-medium leading-relaxed border transition-colors focus:ring-1 focus:ring-cyan-500/50 ${isActive ? 'text-white border-white/10' : 'text-gray-400 border-transparent focus:text-gray-200'}`}
                                        rows={Math.max(1, seg.text.split('\n').length)}
                                        value={seg.text}
                                        onChange={(val) => updateSegmentData(idx, { text: val }, true)} 
                                        onBlur={() => {}} 
                                        placeholder="Enter lyrics here..."
                                    />
                                </div>
                             </div>
                        );
                    } 

                    // --- RENDER EVENT BLOCK ---
                    else {
                        const block = item.data;
                        const isActive = currentTime >= block.start && currentTime <= block.end;

                        return (
                            <div 
                                key={block.id}
                                data-id={block.id}
                                className={`group relative p-3 rounded-lg border border-purple-500/30 transition-all ${
                                    isActive ? 'bg-purple-950/40 shadow-[0_0_15px_rgba(147,51,234,0.1)]' : 'bg-neutral-900/80 hover:bg-neutral-800'
                                }`}
                            >
                                <div className="absolute left-0 top-0 bottom-0 w-1 bg-purple-500 rounded-l-lg"></div>

                                {/* HEADER */}
                                <div className="flex items-center justify-between mb-2 pl-2">
                                     <div className="flex items-center gap-2">
                                         <Zap size={14} className="text-purple-400" />
                                         <input 
                                            value={block.label}
                                            onChange={(e) => updateEventBlock(block.id, { label: e.target.value })}
                                            className="bg-transparent text-xs font-bold text-purple-200 outline-none w-32 border-b border-transparent hover:border-purple-500/50 focus:border-purple-500"
                                         />

                                         {/* FADE CONTROLS */}
                                         <div className="flex items-center gap-1 ml-2 border-l border-white/10 pl-2">
                                             <button 
                                                onClick={() => updateEventBlock(block.id, { smoothIn: !block.smoothIn })}
                                                className={`p-1 rounded ${block.smoothIn ? 'text-green-400 bg-green-950/30' : 'text-gray-600 hover:text-gray-400'}`}
                                                title="Fade In"
                                             >
                                                 <TrendingUp size={12} />
                                             </button>
                                             <button 
                                                onClick={() => updateEventBlock(block.id, { smoothOut: !block.smoothOut })}
                                                className={`p-1 rounded ${block.smoothOut ? 'text-green-400 bg-green-950/30' : 'text-gray-600 hover:text-gray-400'}`}
                                                title="Fade Out"
                                             >
                                                 <TrendingDown size={12} />
                                             </button>
                                         </div>
                                     </div>
                                     <div className="flex items-center gap-2">
                                          <div className="flex items-center gap-1 bg-black/40 rounded px-1.5 py-0.5 border border-white/5">
                                              <TimeInput className="bg-transparent w-12 text-[10px] font-mono text-gray-400 outline-none text-right" value={block.start} onChange={(v) => updateEventBlock(block.id, { start: v })} />
                                              <span className="text-[10px] text-gray-600">-</span>
                                              <TimeInput className="bg-transparent w-12 text-[10px] font-mono text-gray-400 outline-none text-right" value={block.end} onChange={(v) => updateEventBlock(block.id, { end: v })} />
                                          </div>
                                          <button onClick={() => updateEventBlock(block.id, { collapsed: !block.collapsed })} className="p-1 hover:text-white text-gray-500">
                                              {block.collapsed ? <ChevronDown size={14} /> : <ChevronUp size={14} />}
                                          </button>
                                          <button onClick={() => deleteEventBlock(block.id)} className="p-1 hover:text-red-400 text-gray-500">
                                              <Trash2 size={14} />
                                          </button>
                                     </div>
                                </div>

                                {/* ACTIVE OVERRIDES INDICATOR (Collapsed Mode) */}
                                {block.collapsed && (
                                    <div className="flex flex-wrap gap-1 pl-2">
                                        {Object.entries(block.overrides).map(([k, v]) => {
                                            if (k === 'custom_fx') return null; // Handle separately or ignore in summary
                                            return (
                                                <span key={k} className="text-[9px] bg-purple-900/50 text-purple-300 px-1.5 py-0.5 rounded border border-purple-500/20">
                                                    {k.replace('fx_', '').replace('cam_', '')}
                                                </span>
                                            )
                                        })}
                                        {block.overrides.custom_fx && Object.keys(block.overrides.custom_fx).length > 0 && (
                                            <span className="text-[9px] bg-cyan-900/50 text-cyan-300 px-1.5 py-0.5 rounded border border-cyan-500/20">
                                                +{Object.keys(block.overrides.custom_fx).length} Custom
                                            </span>
                                        )}
                                    </div>
                                )}

                                {/* FULL EDITOR (Expanded Mode) */}
                                {!block.collapsed && (
                                    <div className="pl-2 grid grid-cols-2 gap-4 mt-3 pt-3 border-t border-white/5">
                                         {/* VFX */}
                                         <div>
                                             <h4 className="text-[9px] font-bold text-gray-500 uppercase mb-2">Visual FX</h4>
                                             <div className="flex flex-wrap gap-2">
                                                 <EffectToggle label="Glitch" isActive={block.overrides.fx_chromaticAberration} onToggle={() => toggleOverride(block.id, 'fx_chromaticAberration')} />
                                                 <EffectToggle label="VHS" isActive={block.overrides.fx_vhs} onToggle={() => toggleOverride(block.id, 'fx_vhs')} />
                                                 <EffectToggle label="Pixelate" isActive={block.overrides.fx_mosaic} onToggle={() => toggleOverride(block.id, 'fx_mosaic')} />
                                                 <EffectToggle label="Invert" isActive={block.overrides.fx_invert} onToggle={() => toggleOverride(block.id, 'fx_invert')} />
                                                 <EffectToggle label="Mirror" isActive={block.overrides.fx_mirror} onToggle={() => toggleOverride(block.id, 'fx_mirror')} />
                                                 <EffectToggle label="RGB Split" isActive={block.overrides.fx_rgbSplit} onToggle={() => toggleOverride(block.id, 'fx_rgbSplit')} />
                                                 <EffectToggle label="Scanlines" isActive={block.overrides.fx_scanlines} onToggle={() => toggleOverride(block.id, 'fx_scanlines')} />
                                                 <EffectToggle label="Kaleidoscope" isActive={block.overrides.fx_kaleidoscope} onToggle={() => toggleOverride(block.id, 'fx_kaleidoscope')} />
                                                 <EffectToggle label="Halftone" isActive={block.overrides.fx_halftone} onToggle={() => toggleOverride(block.id, 'fx_halftone')} />
                                                 <EffectToggle label="Old Movie" isActive={block.overrides.fx_oldMovie} onToggle={() => toggleOverride(block.id, 'fx_oldMovie')} />
                                             </div>
                                         </div>
                                         {/* Camera */}
                                         <div>
                                             <h4 className="text-[9px] font-bold text-gray-500 uppercase mb-2">Camera</h4>
                                             <div className="flex flex-wrap gap-2">
                                                 <EffectToggle label="Shake" isActive={block.overrides.cam_shake} onToggle={() => toggleOverride(block.id, 'cam_shake')} />
                                                 <EffectToggle label="Zoom Beat" isActive={block.overrides.cam_zoomBeat} onToggle={() => toggleOverride(block.id, 'cam_zoomBeat')} />
                                                 <EffectToggle label="Hard Kick" isActive={block.overrides.cam_hardKick} onToggle={() => toggleOverride(block.id, 'cam_hardKick')} />
                                                 <EffectToggle label="Panic" isActive={block.overrides.cam_panic} onToggle={() => toggleOverride(block.id, 'cam_panic')} />
                                                 <EffectToggle label="Sway" isActive={block.overrides.cam_sway} onToggle={() => toggleOverride(block.id, 'cam_sway')} />
                                                 <EffectToggle label="Rotate" isActive={block.overrides.cam_rotate} onToggle={() => toggleOverride(block.id, 'cam_rotate')} />
                                             </div>
                                             <h4 className="text-[9px] font-bold text-gray-500 uppercase mb-2 mt-3">Particles</h4>
                                             <EffectToggle label="Particles" isActive={block.overrides.part_enabled} onToggle={() => toggleOverride(block.id, 'part_enabled')} />
                                         </div>

                                         {/* Custom Effects */}
                                         {customEffects && customEffects.length > 0 && (
                                             <div className="col-span-2 pt-3 mt-3 border-t border-white/5">
                                                 <h4 className="text-[9px] font-bold text-cyan-500 uppercase mb-2">Custom Effects</h4>
                                                 <div className="flex flex-wrap gap-2">
                                                     {customEffects.map(fx => (
                                                         <EffectToggle 
                                                            key={fx.id} 
                                                            label={fx.name} 
                                                            isActive={block.overrides.custom_fx?.[fx.id]} 
                                                            onToggle={() => toggleCustomOverride(block.id, fx.id)} 
                                                         />
                                                     ))}
                                                 </div>
                                             </div>
                                         )}
                                    </div>
                                )}
                            </div>
                        );
                    }
                })
            )}

            <div className="h-20"></div>
        </div>
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { Sliders, LayoutTemplate, Palette, Sparkles, Video, Type, Image as ImageIcon, Upload, Grid, Music, Camera, Aperture, Clock, Plus, Trash2, Monitor, Timer, FolderOpen, FileJson, FileText, FileAudio, Volume2, VolumeX, Mic2, Layers, AlignLeft, Tags, RotateCcw, AlignJustify, Code, Download, BookOpen, Edit2, Play } from 'lucide-react';
import { TEMPLATES, FONTS, RESOLUTIONS, TEMPLATE_SHADER_GLSL, TEMPLATE_CAMERA_JS, TEMPLATE_EVENT_PRESET } from '../constants';
import { RendererConfig, AnimationKeyframe, AudioLayer, LyricData, SectionType, SectionStyle, ImageEffect, ProceduralStyle, EventBlock, CustomEffect, CustomEffectType } from '../types';
import { TimelineEditor } from './TimelineEditor';

interface SettingsPanelProps {
  config: RendererConfig;
  onUpdate: (config: RendererConfig) => void;
  // Lyrics Data
  data: LyricData;
  onUpdateData: (data: LyricData) => void;
  // Playback
  currentTime: number;
  onSeek: (time: number) => void;
  // File Handlers
  onJsonUpload: (jsonStr: string) => void;
  onSrtUpload: (srtStr: string) => void;
  onAudioLayerAdd: (file: File) => void;
  // Audio Mixer Handlers
  audioLayers: AudioLayer[];
  onUpdateLayer: (id: string, updates: Partial<AudioLayer>) => void;
  onRemoveLayer: (id: string) => void;
  // Project Management
  onResetProject: () => void;
  // Event Blocks
  eventBlocks: EventBlock[];
  onUpdateEventBlocks: (blocks: EventBlock[]) => void;
  // Asset Management (New)
  onAssetLoaded?: (type: 'background' | 'font', file: File, meta?: string) => void;
  // Custom Effects (New)
  customEffects?: CustomEffect[];
  onUpdateCustomEffects?: (fx: CustomEffect[]) => void;
}

// Helper Components
const ToggleInput: React.FC<{ label: string, value: boolean, onChange: (v: boolean) => void }> = ({ label, value, onChange }) => (
  <div className="flex items-center justify-between">
    <span className="text-sm font-medium text-gray-400">{label}</span>
    <button
      onClick={() => onChange(!value)}
      className={`w-10 h-5 rounded-full relative transition-colors ${value ? 'bg-cyan-600' : 'bg-neutral-700'}`}
    >
      <div className={`absolute top-1 left-1 w-3 h-3 bg-white rounded-full transition-transform ${value ? 'translate-x-5' : 'translate-x-0'}`} />
    </button>
  </div>
);

const ColorInput: React.FC<{ label: string, value: string, onChange: (v: string) => void }> = ({ label, value, onChange }) => (
  <div className="flex items-center justify-between bg-neutral-900 p-2 rounded-md border border-white/5">
    <span className="text-xs font-bold text-gray-400">{label}</span>
    <div className="flex items-center gap-2">
      <div className="w-4 h-4 rounded-full border border-white/20" style={{ background: value }}></div>
      <input
        type="color"
        value={value}
        onChange={(e) => onChange(e.target.value)}
        className="opacity-0 absolute w-8 h-8 cursor-pointer"
      />
      <span className="text-xs font-mono text-gray-500">{value}</span>
    </div>
  </div>
);

export const SettingsPanel: React.FC<SettingsPanelProps> = ({ 
    config, 
    onUpdate, 
    data,
    onUpdateData,
    currentTime,
    onSeek,
    onAudioLayerAdd,
    audioLayers,
    onUpdateLayer,
    onRemoveLayer,
    onJsonUpload,
    onSrtUpload,
    onResetProject,
    eventBlocks,
    onUpdateEventBlocks,
    onAssetLoaded,
    customEffects = [],
    onUpdateCustomEffects
}) => {
  const [activeTab, setActiveTab] = useState<'project' | 'lyrics' | 'sections' | 'templates' | 'customize' | 'library' | 'guide'>('project');
  const [editingEffect, setEditingEffect] = useState<CustomEffect | null>(null);

  const bgInputRef = useRef<HTMLInputElement>(null);
  const fontInputRef = useRef<HTMLInputElement>(null);
  const jsonInputRef = useRef<HTMLInputElement>(null);
  const srtInputRef = useRef<HTMLInputElement>(null);
  const audioInputRef = useRef<HTMLInputElement>(null);

  const handleTemplateSelect = (template: RendererConfig) => {
    onUpdate(JSON.parse(JSON.stringify(template)));
  };

  const updateNested = (section: keyof RendererConfig, key: string, value: any) => {
    const newConfig = JSON.parse(JSON.stringify(config));
    // @ts-ignore
    newConfig[section][key] = value;
    onUpdate(newConfig);
  };

  const updateSectionStyle = (section: SectionType, key: keyof SectionStyle, value: any) => {
      const newConfig = JSON.parse(JSON.stringify(config));
      if (!newConfig.sectionStyles) newConfig.sectionStyles = {};
      if (!newConfig.sectionStyles[section]) newConfig.sectionStyles[section] = { enabled: false };

      // @ts-ignore
      newConfig.sectionStyles[section][key] = value;
      onUpdate(newConfig);
  };

  const handleBgUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          const url = URL.createObjectURL(file);
          const type = file.type.startsWith('video') ? 'video' : 'image';

          const newConfig = JSON.parse(JSON.stringify(config));
          newConfig.background.type = type;
          newConfig.background.url = url;
          onUpdate(newConfig);
          if(onAssetLoaded) onAssetLoaded('background', file);
      }
  };

  const handleFontUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
       const reader = new FileReader();
       reader.onload = (ev) => {
           if(ev.target?.result) {
               const fontName = 'CustomFont-' + Date.now();
               const fontFace = new FontFace(fontName, `url(${ev.target.result})`);
               fontFace.load().then((loadedFace) => {
                   document.fonts.add(loadedFace);
                   updateNested('font', 'family', fontName);
                   if(onAssetLoaded) onAssetLoaded('font', file, fontName);
               }).catch(err => console.error("Font load failed", err));
           }
       };
       reader.readAsDataURL(file);
    }
  };

  const handleJsonChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      if (event.target?.result) onJsonUpload(event.target.result as string);
    };
    reader.readAsText(file);
  };

  const handleSrtChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      if (event.target?.result) onSrtUpload(event.target.result as string);
    };
    reader.readAsText(file);
  };

  const handleAudioChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
        onAudioLayerAdd(file);
        if (audioInputRef.current) audioInputRef.current.value = '';
    }
  };

  // --- CUSTOM EFFECT HANDLERS ---
  const addNewEffect = (type: CustomEffectType) => {
      const newFx: CustomEffect = {
          id: `fx-${Date.now()}`,
          name: `New ${type === 'shader' ? 'Shader' : 'Camera'}`,
          type,
          code: type === 'shader' ? TEMPLATE_SHADER_GLSL : TEMPLATE_CAMERA_JS,
          active: false,
          description: "My custom effect"
      };
      if (onUpdateCustomEffects) onUpdateCustomEffects([...customEffects, newFx]);
      setEditingEffect(newFx);
  };

  const saveEffect = (fx: CustomEffect) => {
      if (!onUpdateCustomEffects) return;
      const exists = customEffects.find(e => e.id === fx.id);
      if (exists) {
          onUpdateCustomEffects(customEffects.map(e => e.id === fx.id ? fx : e));
      } else {
          onUpdateCustomEffects([...customEffects, fx]);
      }
      setEditingEffect(null);
  };

  const deleteEffect = (id: string) => {
      if (!onUpdateCustomEffects || !confirm("Delete this effect permanently?")) return;
      onUpdateCustomEffects(customEffects.filter(e => e.id !== id));
      if (editingEffect?.id === id) setEditingEffect(null);
  };

  const toggleEffect = (id: string) => {
      if (!onUpdateCustomEffects) return;
      onUpdateCustomEffects(customEffects.map(e => e.id === id ? { ...e, active: !e.active } : e));
  };

  const downloadTemplate = (content: string, filename: string) => {
      const blob = new Blob([content], { type: 'text/plain' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = filename;
      a.click();
      URL.revokeObjectURL(url);
  };

  return (
    <div className="h-full flex flex-col bg-neutral-800 border-r border-white/5 text-gray-200">

      {/* Tab Navigation */}
      <div className="flex border-b border-white/5 bg-neutral-900 overflow-x-auto no-scrollbar">
        {[
            { id: 'project', icon: FolderOpen, label: 'Files' },
            { id: 'lyrics', icon: Clock, label: 'Timeline' },
            { id: 'sections', icon: Tags, label: 'Parts' },
            { id: 'templates', icon: LayoutTemplate, label: 'Presets' },
            { id: 'customize', icon: Sliders, label: 'Style' },
            { id: 'library', icon: Code, label: 'Library' },
            { id: 'guide', icon: BookOpen, label: 'Guide' },
        ].map(tab => (
            <button 
              key={tab.id}
              onClick={() => setActiveTab(tab.id as any)}
              title={tab.label}
              className={`flex-1 min-w-[50px] py-4 text-[10px] font-bold uppercase flex flex-col items-center justify-center gap-1 transition-colors border-b-2 ${activeTab === tab.id ? 'text-cyan-400 border-cyan-400 bg-white/5' : 'text-gray-500 hover:text-gray-300 border-transparent'}`}
            >
              <tab.icon size={16} />
              {tab.label}
            </button>
        ))}
      </div>

      {/* Content Area */}
      <div className="flex-1 overflow-y-auto custom-scrollbar bg-neutral-800">

        {/* PROJECT TAB */}
        {activeTab === 'project' && (
             <div className="p-4 space-y-6">

                {/* Audio Mixer */}
                <section>
                    <div className="flex items-center justify-between mb-3">
                         <h3 className="text-xs font-bold text-gray-500 uppercase tracking-widest flex items-center gap-2">
                            <Layers size={14}/> Audio Mixer
                        </h3>
                        <button
                             onClick={() => audioInputRef.current?.click()}
                             className="text-[10px] bg-neutral-700 hover:bg-neutral-600 px-2 py-1 rounded flex items-center gap-1 transition-colors"
                        >
                            <Plus size={10} /> Add Layer
                        </button>
                        <input
                            type="file"
                            ref={audioInputRef}
                            onChange={handleAudioChange}
                            accept="audio/*"
                            className="hidden"
                        />
                    </div>

                    <div className="space-y-2">
                        {audioLayers.length === 0 ? (
                            <div className="text-center p-4 border border-dashed border-white/10 rounded-lg text-xs text-gray-500">
                                No audio tracks loaded.
                            </div>
                        ) : (
                            audioLayers.map(layer => (
                                <div key={layer.id} className="bg-neutral-900 border border-white/5 rounded-lg p-2.5">
                                    <div className="flex items-center justify-between mb-2">
                                        <div className="flex items-center gap-2 overflow-hidden">
                                            <Music size={12} className="text-cyan-500 shrink-0"/>
                                            <span className="text-xs font-bold truncate text-gray-300" title={layer.name}>{layer.name}</span>
                                        </div>
                                        <button 
                                            onClick={() => onRemoveLayer(layer.id)}
                                            className="text-neutral-500 hover:text-red-400 transition-colors"
                                        >
                                            <Trash2 size={12}/>
                                        </button>
                                    </div>

                                    <div className="flex items-center gap-2">
                                        <input 
                                            type="range" min="0" max="1" step="0.01"
                                            value={layer.volume}
                                            onChange={(e) => onUpdateLayer(layer.id, { volume: parseFloat(e.target.value) })}
                                            className="flex-1 h-1 bg-neutral-700 rounded-lg appearance-none cursor-pointer accent-cyan-400"
                                            title={`Volume: ${Math.round(layer.volume * 100)}%`}
                                        />
                                        <div className="flex items-center gap-1 shrink-0">
                                            <button
                                                onClick={() => onUpdateLayer(layer.id, { muted: !layer.muted })}
                                                className={`w-6 h-6 rounded flex items-center justify-center text-[10px] font-bold border transition-colors ${layer.muted ? 'bg-red-900/50 border-red-500/50 text-red-400' : 'bg-neutral-800 border-white/5 text-gray-400 hover:text-white'}`}
                                                title="Mute"
                                            >
                                                M
                                            </button>
                                            <button
                                                onClick={() => onUpdateLayer(layer.id, { solo: !layer.solo })}
                                                className={`w-6 h-6 rounded flex items-center justify-center text-[10px] font-bold border transition-colors ${layer.solo ? 'bg-yellow-900/50 border-yellow-500/50 text-yellow-400' : 'bg-neutral-800 border-white/5 text-gray-400 hover:text-white'}`}
                                                title="Solo"
                                            >
                                                S
                                            </button>
                                        </div>
                                    </div>
                                </div>
                            ))
                        )}
                    </div>
                </section>

                <section>
                    <h3 className="text-xs font-bold text-gray-500 uppercase tracking-widest mb-3 flex items-center gap-2">
                        <Type size={14}/> Lyrics Source
                    </h3>
                    <div className="grid grid-cols-2 gap-3">
                         <button
                            onClick={() => jsonInputRef.current?.click()}
                            className="flex flex-col items-center justify-center gap-2 p-4 bg-neutral-900 hover:bg-neutral-700 rounded-lg border border-white/5 transition-colors group"
                        >
                            <FileJson size={24} className="text-gray-500 group-hover:text-purple-400" />
                            <span className="text-xs font-bold text-gray-400 group-hover:text-white">Import JSON</span>
                        </button>
                        <input
                            type="file"
                            ref={jsonInputRef}
                            onChange={handleJsonChange}
                            accept=".json,application/json"
                            className="hidden"
                        />

                         <button
                            onClick={() => srtInputRef.current?.click()}
                            className="flex flex-col items-center justify-center gap-2 p-4 bg-neutral-900 hover:bg-neutral-700 rounded-lg border border-white/5 transition-colors group"
                        >
                            <FileText size={24} className="text-gray-500 group-hover:text-orange-400" />
                            <span className="text-xs font-bold text-gray-400 group-hover:text-white">Import SRT</span>
                        </button>
                        <input
                            type="file"
                            ref={srtInputRef}
                            onChange={handleSrtChange}
                            accept=".srt"
                            className="hidden"
                        />
                    </div>
                </section>

                <section>
                    <h3 className="text-xs font-bold text-gray-500 uppercase tracking-widest mb-3 flex items-center gap-2">
                         <ImageIcon size={14}/> Assets
                    </h3>
                    <div className="space-y-2">
                         <button 
                            onClick={() => bgInputRef.current?.click()}
                            className="w-full flex items-center justify-start gap-3 px-3 py-2 bg-neutral-900 hover:bg-neutral-700 rounded-lg border border-white/5 transition-colors text-sm text-gray-300"
                        >
                            <Upload size={16} className="text-gray-500"/>
                            Upload Background Media
                        </button>
                        <input type="file" ref={bgInputRef} onChange={handleBgUpload} accept="image/*,video/*" className="hidden"/>

                        <button 
                            onClick={() => fontInputRef.current?.click()}
                            className="w-full flex items-center justify-start gap-3 px-3 py-2 bg-neutral-900 hover:bg-neutral-700 rounded-lg border border-white/5 transition-colors text-sm text-gray-300"
                        >
                             <Type size={16} className="text-gray-500"/>
                             Upload Custom Font
                        </button>
                        <input type="file" ref={fontInputRef} onChange={handleFontUpload} accept=".ttf,.woff,.woff2,.otf" className="hidden"/>
                    </div>
                </section>

                <section className="pt-4 border-t border-white/5">
                    <button
                        onClick={onResetProject}
                        className="w-full flex items-center justify-center gap-2 px-3 py-2 bg-red-950/30 hover:bg-red-900/50 text-red-400 rounded-lg border border-red-900/50 transition-colors text-sm font-bold"
                    >
                        <Trash2 size={16} />
                        Reset Project Defaults
                    </button>
                </section>
             </div>
        )}

        {/* TIMELINE TAB */}
        {activeTab === 'lyrics' && (
            <TimelineEditor 
                data={data} 
                onUpdate={onUpdateData} 
                currentTime={currentTime}
                onSeek={onSeek}
                eventBlocks={eventBlocks}
                onUpdateEventBlocks={onUpdateEventBlocks}
                customEffects={customEffects}
            />
        )}

        {/* CUSTOMIZE TAB */}
        {activeTab === 'customize' && (
          <div className="p-4 space-y-6">
              <section>
                  <h3 className="text-xs font-bold text-gray-500 uppercase tracking-widest mb-3 flex items-center gap-2"><Aperture size={14}/> Global Effects</h3>
                  <div className="bg-neutral-900 p-3 rounded-lg border border-white/5 space-y-2">
                        <ToggleInput label="Chromatic Ab." value={config.effects.chromaticAberration} onChange={(v) => updateNested('effects', 'chromaticAberration', v)} />
                        <ToggleInput label="Scanlines" value={config.effects.scanlines} onChange={(v) => updateNested('effects', 'scanlines', v)} />
                        <ToggleInput label="Vignette" value={config.effects.vignette} onChange={(v) => updateNested('effects', 'vignette', v)} />
                        <ToggleInput label="Film Grain" value={config.effects.filmGrain} onChange={(v) => updateNested('effects', 'filmGrain', v)} />
                        <ToggleInput label="Glow" value={config.effects.glow > 0} onChange={(v) => updateNested('effects', 'glow', v ? 0.8 : 0)} />
                  </div>
              </section>

              {/* ACTIVE CUSTOM EFFECTS LIST IN CUSTOMIZE TAB */}
              {customEffects && customEffects.length > 0 && (
                  <section>
                      <h3 className="text-xs font-bold text-purple-500 uppercase tracking-widest mb-3 flex items-center gap-2"><Code size={14}/> User Effects</h3>
                      <div className="bg-neutral-900 p-3 rounded-lg border border-white/5 space-y-2">
                          {customEffects.map(fx => (
                              <ToggleInput 
                                key={fx.id} 
                                label={fx.name} 
                                value={fx.active} 
                                onChange={() => toggleEffect(fx.id)} 
                              />
                          ))}
                      </div>
                  </section>
              )}
          </div>
        )}

        {/* LIBRARY TAB */}
        {activeTab === 'library' && (
            <div className="p-4 space-y-6">
                {!editingEffect ? (
                    <>
                        <div className="flex gap-2 mb-4">
                            <button onClick={() => addNewEffect('shader')} className="flex-1 bg-cyan-900/40 border border-cyan-500/30 hover:bg-cyan-800/50 text-cyan-200 py-2 rounded-lg text-xs font-bold flex items-center justify-center gap-2">
                                <Plus size={14}/> New Shader FX
                            </button>
                            <button onClick={() => addNewEffect('camera')} className="flex-1 bg-purple-900/40 border border-purple-500/30 hover:bg-purple-800/50 text-purple-200 py-2 rounded-lg text-xs font-bold flex items-center justify-center gap-2">
                                <Plus size={14}/> New Camera FX
                            </button>
                        </div>

                        <div className="space-y-3">
                            {customEffects.length === 0 ? (
                                <div className="text-center text-gray-500 py-8 text-xs italic">
                                    No custom effects created yet.<br/>Use the buttons above or download templates from the Guide.
                                </div>
                            ) : (
                                customEffects.map(fx => (
                                    <div key={fx.id} className="bg-neutral-900 border border-white/5 rounded-lg p-3 group">
                                        <div className="flex items-center justify-between mb-2">
                                            <div className="flex items-center gap-2">
                                                <div className={`w-2 h-2 rounded-full ${fx.type === 'shader' ? 'bg-cyan-500' : 'bg-purple-500'}`} />
                                                <span className="font-bold text-sm text-gray-200">{fx.name}</span>
                                                {fx.active && <span className="text-[9px] bg-green-900 text-green-300 px-1 rounded uppercase">Active</span>}
                                            </div>
                                            <div className="flex gap-1">
                                                <button onClick={() => setEditingEffect(fx)} className="p-1.5 hover:bg-white/10 rounded text-gray-400 hover:text-white" title="Edit Code">
                                                    <Edit2 size={14}/>
                                                </button>
                                                <button onClick={() => toggleEffect(fx.id)} className="p-1.5 hover:bg-white/10 rounded text-gray-400 hover:text-white" title={fx.active ? "Disable" : "Enable"}>
                                                    <Play size={14} fill={fx.active ? "currentColor" : "none"}/>
                                                </button>
                                                <button onClick={() => deleteEffect(fx.id)} className="p-1.5 hover:bg-red-900/50 rounded text-gray-400 hover:text-red-400" title="Delete">
                                                    <Trash2 size={14}/>
                                                </button>
                                            </div>
                                        </div>
                                        <p className="text-[10px] text-gray-500 line-clamp-2 font-mono bg-black/30 p-1.5 rounded">
                                            {fx.description || "// No description"}
                                        </p>
                                    </div>
                                ))
                            )}
                        </div>
                    </>
                ) : (
                    <div className="flex flex-col h-full">
                        <div className="flex items-center justify-between mb-2">
                            <input 
                                value={editingEffect.name}
                                onChange={(e) => setEditingEffect({...editingEffect, name: e.target.value})}
                                className="bg-transparent text-sm font-bold border-b border-transparent focus:border-cyan-500 outline-none w-1/2"
                                placeholder="Effect Name"
                            />
                            <div className="flex gap-2">
                                <button onClick={() => setEditingEffect(null)} className="text-xs text-gray-400 hover:text-white">Cancel</button>
                                <button onClick={() => saveEffect(editingEffect)} className="text-xs bg-cyan-600 px-3 py-1 rounded text-white font-bold">Save</button>
                            </div>
                        </div>
                        <input 
                            value={editingEffect.description || ''}
                            onChange={(e) => setEditingEffect({...editingEffect, description: e.target.value})}
                            className="bg-neutral-900 text-xs text-gray-400 p-2 rounded mb-2 w-full outline-none"
                            placeholder="Short description..."
                        />
                        <div className="flex-1 bg-neutral-950 rounded border border-white/10 p-2 overflow-hidden flex flex-col">
                            <div className="text-[10px] text-gray-500 mb-1 font-mono">{editingEffect.type === 'shader' ? '// GLSL Fragment Shader Body' : '// JavaScript Camera Logic'}</div>
                            <textarea 
